<?php
namespace App\Http\Controllers; use App\Models\{Sale,Item,SaleItem,SalePayment,StockMovement}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class SaleController extends Controller {public function index(Request $r){$q=Sale::with('items.item')->orderByDesc('sale_date');if($r->filled('from'))$q->whereDate('sale_date','>=',$r->from);if($r->filled('to'))$q->whereDate('sale_date','<=',$r->to);return view('sales.index',['sales'=>$q->paginate(20)->withQueryString()]);} public function create(){return view('sales.form',['items'=>Item::where('quantity','>',0)->orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['sale_date'=>'required|date','customer_name'=>'nullable|string|max:255','item_id'=>'required|exists:items,id','quantity'=>'required|integer|min:1','unit_price'=>'required|numeric|min:0','discount'=>'nullable|numeric|min:0','paid_amount'=>'required|numeric|min:0','sale_type'=>'required|in:Item,Software','notes'=>'nullable|string']);DB::transaction(function()use($d){$item=Item::lockForUpdate()->findOrFail($d['item_id']);if($d['sale_type']==='Item' && $item->quantity<$d['quantity'])throw ValidationException::withMessages(['quantity'=>'Stock mein itni quantity mojood nahi.']);$subtotal=$d['quantity']*$d['unit_price'];$total=max(0,$subtotal-($d['discount']??0));if($d['paid_amount']>$total)throw ValidationException::withMessages(['paid_amount'=>'Received amount total se zyada nahi ho sakta.']);$sale=Sale::create(['invoice_no'=>'STH-'.now()->format('ymdHis').'-'.random_int(10,99),'customer_name'=>$d['customer_name']??null,'sale_date'=>$d['sale_date'],'subtotal'=>$subtotal,'discount'=>$d['discount']??0,'total'=>$total,'paid_amount'=>$d['paid_amount'],'sale_type'=>$d['sale_type'],'notes'=>$d['notes']??null]);SaleItem::create(['sale_id'=>$sale->id,'item_id'=>$item->id,'quantity'=>$d['quantity'],'unit_price'=>$d['unit_price'],'unit_cost'=>$item->buying_price,'line_total'=>$total]);if($d['sale_type']==='Item'){$item->decrement('quantity',$d['quantity']);StockMovement::create(['item_id'=>$item->id,'movement_type'=>'sale','quantity'=>$d['quantity'],'reference'=>$sale->invoice_no,'movement_date'=>$d['sale_date']]);}if($d['paid_amount']>0)SalePayment::create(['sale_id'=>$sale->id,'payment_date'=>$d['sale_date'],'amount'=>$d['paid_amount'],'method'=>'Cash']);});return redirect('/sales')->with('success','Sale record save ho gaya.');} public function show(Sale $sale){$sale->load('items.item','payments');return view('sales.show',compact('sale'));} public function payment(Request $r,Sale $sale){$d=$r->validate(['payment_date'=>'required|date','amount'=>'required|numeric|min:0.01','method'=>'required|string|max:40','notes'=>'nullable|string']);if($d['amount']>$sale->total-$sale->paid_amount)throw ValidationException::withMessages(['amount'=>'Payment due amount se zyada hai.']);DB::transaction(function()use($d,$sale){$sale->payments()->create($d);$sale->increment('paid_amount',$d['amount']);});return back()->with('success','Payment receive ho gayi.');}}
